package com.slotmind.entity;
import com.slotmind.enums.*; import jakarta.persistence.*; import java.time.Instant;
@Entity
 public class RescheduleSuggestion { @Id private String id; @ManyToOne(fetch=FetchType.EAGER,optional=false) private Appointment appointment; @ManyToOne(fetch=FetchType.EAGER,optional=false) private Slot recommendedSlot; @ManyToOne(fetch=FetchType.EAGER) private Provider alternateProvider; private String originalProviderName; private Instant originalTime; private double confidence; @Column(length=1000) private String reasoning; private String source; @Enumerated(EnumType.STRING) private SuggestionStatus status; @Enumerated(EnumType.STRING) private TriggerReason triggerReason; private Instant createdAt; @Version private long version;
  public RescheduleSuggestion(){} public RescheduleSuggestion(String id,Appointment a,Slot s,Provider p,String originalProviderName,Instant originalTime,double c,String r,String source,SuggestionStatus st,TriggerReason tr,Instant t,long v){this.id=id;appointment=a;recommendedSlot=s;alternateProvider=p;this.originalProviderName=originalProviderName;this.originalTime=originalTime;confidence=c;reasoning=r;this.source=source;status=st;triggerReason=tr;createdAt=t;version=v;} public String getId(){return id;} public Appointment getAppointment(){return appointment;} public Slot getRecommendedSlot(){return recommendedSlot;} public String getOriginalProviderName(){return originalProviderName;} public Instant getOriginalTime(){return originalTime;} public double getConfidence(){return confidence;} public String getReasoning(){return reasoning;} public String getSource(){return source;} public SuggestionStatus getStatus(){return status;} public TriggerReason getTriggerReason(){return triggerReason;} public void setStatus(SuggestionStatus s){status=s;}
}